import "server-only";
import { unstable_cache } from "next/cache";
import catalog from "../../../data/catalog/products.json";
import { type WorldSlug, worlds } from "@/config/catalog";
import { getEnv } from "@/lib/server/env";
import type { Product } from "./types";

// The catalogue is generated by `npm run catalog` (scripts/build-catalog.mjs)
// from the EDELRID price lists and edelrid.com. Prices published from the admin
// price-list import (D1 table price_overrides) are applied on top. Net (dealer)
// prices live in a separate file that is never imported here.

/** Catalogue as built, without admin price overrides. Use for routing and metadata only. */
export const baseProducts = catalog.products as unknown as Product[];
export const catalogGeneratedAt = catalog.generatedAt;

/** Published RRP overrides in cents, keyed by item number. Revalidated with the "prices" tag. */
export const getPriceOverrides = unstable_cache(readPriceOverrides, ["price-overrides"], { tags: ["prices"], revalidate: false });

async function readPriceOverrides(): Promise<Record<string, number>> {
  const env = await getEnv();
  if (!env.DB) return {};
  try {
    const { results } = await env.DB.prepare("SELECT sku, rrp_cents FROM price_overrides").all<{ sku: string; rrp_cents: number }>();
    return Object.fromEntries(results.map((r) => [r.sku, r.rrp_cents]));
  } catch {
    // table missing (migrations not applied yet)
    return {};
  }
}

export type Catalog = ReturnType<typeof buildCatalog>;

function buildCatalog(products: Product[]) {
  const bySlug = new Map(products.map((p) => [p.slug, p]));
  const bySku = new Map(products.flatMap((p) => p.variants.map((v) => [v.sku, { product: p, variant: v }] as const)));
  const isListedIn = (p: Product, world: WorldSlug, sub?: string) =>
    (p.mainCategory === world && (!sub || p.subcategory === sub)) ||
    (p.alsoIn ?? []).some((a) => a.mainCategory === world && (!sub || a.subcategory === sub));

  return {
    products,
    getProduct: (slug: string) => bySlug.get(slug),
    getProducts: (slugs: string[]) => slugs.map((s) => bySlug.get(s)).filter((p): p is Product => Boolean(p)),
    /** Product and variant for an EDELRID item number. */
    getVariant: (sku: string) => bySku.get(sku),
    /** Products shown in a world or subcategory (including "also listed in"). */
    productsIn: (world: WorldSlug, sub?: string) => products.filter((p) => isListedIn(p, world, sub)),
    /** A varied home-page selection: new 2026 products with photos and data, one per subcategory. */
    featured(limit = 8) {
      const picked: Product[] = [];
      const seen = new Set<string>();
      const pool = products
        .filter((p) => p.images.length && p.source && p.certifications.length)
        .sort((a, b) => Number(Boolean(b.isNew)) - Number(Boolean(a.isNew)) || a.rank - b.rank);
      for (const p of pool) {
        const key = `${p.mainCategory}/${p.subcategory}`;
        if (seen.has(key)) continue;
        seen.add(key);
        picked.push(p);
        if (picked.length === limit) break;
      }
      return picked;
    },
  };
}

const base = buildCatalog(baseProducts);
let memo: { key: string; value: Catalog } = { key: "{}", value: base };

/** The catalogue with published price overrides applied. */
export async function getCatalog(): Promise<Catalog> {
  const overrides = await getPriceOverrides();
  const key = JSON.stringify(overrides);
  if (memo.key === key) return memo.value;
  const products = Object.keys(overrides).length
    ? baseProducts.map((p) =>
        p.variants.some((v) => overrides[v.sku] != null)
          ? { ...p, variants: p.variants.map((v) => (overrides[v.sku] != null ? { ...v, price: overrides[v.sku] / 100 } : v)) }
          : p,
      )
    : baseProducts;
  memo = { key, value: buildCatalog(products) };
  return memo.value;
}

/** Number of products per world and "world/sub" (independent of prices). */
export const categoryCounts: Record<string, number> = (() => {
  const counts: Record<string, number> = {};
  for (const w of worlds) {
    counts[w.slug] = base.productsIn(w.slug).length;
    for (const s of w.subcategories) counts[`${w.slug}/${s.slug}`] = base.productsIn(w.slug, s.slug).length;
  }
  return counts;
})();

/** Routing lookups that do not depend on prices. */
export const getBaseProduct = base.getProduct;
